func TestDataEmission(t *testing.T) {
	p := fixture()
	option(p)
	addFunc(p, "none", nil, nil, ctor("None"))
	addFunc(p, "some", nil, nil, call(ctor("Some"), integer(7)))
	f := addFunc(p, "constructor", nil, nil, call(local("make", fnType(types.Int)), integer(9)))
	f.Decl.Body.Stmts = []ast.Stmt{&ast.LetStmt{Name: "make", Value: ctor("Some")}}
	assertSource(t, p,
		"// Code generated by gofx. DO NOT EDIT.",
		"type Option interface{ isOption() }",
		"type Option_None struct{}",
		"type Option_Some struct {",
		"F0 any",
		"func (*Option_Some) isOption()",
		"return &Option_None{}",
		"return &Option_Some{F0: int64(7)}",
		"var make_ any = func(a0 any) any { return &Option_Some{F0: a0} }",
		"any(make_).(func(any) any)(int64(9))",
		"func main() { rt.RunMain(main_()) }")
}

func TestClassesAndSuperclassInstances(t *testing.T) {
	p, functor, monad := classFixture()
	fn := method("pure", fnType(types.Int), instanceDict(monad))
	addFunc(p, "wrap", nil, nil, call(fn, integer(1)))
	fmap := method("fmap", fnType(types.Unit, fnType(types.Int)), instanceDict(functor))
	addFunc(p, "mapped", nil, nil, call(fmap, call(ctor("Some"), integer(1)), identity()))
	assertSource(t, p,
		"type Functor interface {",
		"Fmap(a0 any, a1 any) any",
		"type Monad interface {\n\tFunctor",
		"Pure(a0 any) any",
		"Bind(a0 any, a1 any) any",
		"type Functor_Option struct{}",
		"type Monad_Option struct {\n\tFunctor_Option",
		"func (Functor_Option) Fmap(fa_ any, f_ any) any",
		"func (Monad_Option) Bind(ma_ any, f_ any) any",
		"(Monad_Option{}).Pure(int64(1))",
		"(Functor_Option{}).Fmap(")
}

func TestDictionaryPassingAndFunctionValues(t *testing.T) {
	p, functor, _ := classFixture()
	ft := fnType(types.Unit, fnType(types.Int))
	param := types.DictRef{Kind: types.DictParam, Class: "Functor", Param: "F", ParamClass: "Functor"}
	methodRef := method("fmap", ft, param)
	f := addFunc(p, "twice", []string{"fa", "f"}, ft.Params,
		call(methodRef, call(method("fmap", ft, param), local("fa", types.Unit), local("f", fnType(types.Int))), local("f", fnType(types.Int))))
	f.Scheme.Constraints = []types.Constraint{{Class: "Functor", Arg: &types.TVar{Name: "F"}}}
	addFunc(p, "concrete", nil, nil, call(function("twice", ft, instanceDict(functor)), call(ctor("Some"), integer(3)), identity()))

	monadParam := types.DictRef{Kind: types.DictParam, Class: "Monad", Param: "M", ParamClass: "Monad"}
	super := types.DictRef{Kind: types.DictSuper, Class: "Functor", Super: &monadParam}
	forward := addFunc(p, "forward", []string{"x", "f"}, ft.Params,
		call(function("twice", ft, super), local("x", types.Unit), local("f", fnType(types.Int))))
	forward.Scheme.Constraints = []types.Constraint{{Class: "Monad", Arg: &types.TVar{Name: "M"}}}

	bound := addFunc(p, "bound", []string{"x", "f"}, ft.Params,
		call(local("apply", ft), local("x", types.Unit), local("f", fnType(types.Int))))
	bound.Scheme.Constraints = f.Scheme.Constraints
	bound.Decl.Body.Stmts = []ast.Stmt{&ast.LetStmt{Name: "apply", Value: function("twice", ft, param)}}
	methodValue := addFunc(p, "methodValue", nil, nil,
		call(local("apply", ft), call(ctor("Some"), integer(4)), identity()))
	methodValue.Decl.Body.Stmts = []ast.Stmt{&ast.LetStmt{Name: "apply", Value: method("fmap", ft, instanceDict(functor))}}
	assertSource(t, p,
		"func twice_(dict_F Functor, fa_ any, f_ any) any",
		"(dict_F).Fmap((dict_F).Fmap(fa_, f_), f_)",
		"twice_(Functor_Option{}, &Option_Some{F0: int64(3)}",
		"func forward_(dict_M Monad, x_ any, f_ any) any",
		"twice_(dict_M, x_, f_)",
		"func(a0 any, a1 any) any { return twice_(dict_F, a0, a1) }",
		"any(apply_).(func(any, any) any)(x_, f_)",
		"var apply_ any = (Functor_Option{}).Fmap")
}

func TestMethodOwnDictionaryConstraints(t *testing.T) {
	p, functor, _ := classFixture()
	scheme := functor.Class.Methods[0].Scheme
	scheme.TParams = []*types.TVar{{Name: "G"}}
	scheme.Constraints = []types.Constraint{{Class: "Functor", Arg: scheme.TParams[0]}}
	ref := method("fmap", scheme.Type, instanceDict(functor))
	types.AnnOf(ref).Dicts = append(types.AnnOf(ref).Dicts, instanceDict(functor))
	addFunc(p, "direct", nil, nil, call(ref, call(ctor("Some"), integer(1)), identity()))
	bound := addFunc(p, "bound", nil, nil, call(local("apply", scheme.Type), call(ctor("Some"), integer(2)), identity()))
	bound.Decl.Body.Stmts = []ast.Stmt{&ast.LetStmt{Name: "apply", Value: ref}}
	assertSource(t, p,
		"Fmap(dict_G Functor, a0 any, a1 any) any",
		"func (Functor_Option) Fmap(dict_G Functor, fa_ any, f_ any) any",
		"(Functor_Option{}).Fmap(Functor_Option{}, &Option_Some{F0: int64(1)}",
		"return (Functor_Option{}).Fmap(Functor_Option{}, a0, a1)")
}

func TestDoDesugaring(t *testing.T) {
	p, _, monad := classFixture()
	dict := instanceDict(monad)
	do := &ast.Do{
		ExprBase: annotated(&types.Ann{Type: types.Unit, Monad: &dict}),
		Stmts: []ast.DoStmt{
			&ast.DoBind{Name: "x", X: call(ctor("Some"), integer(1))},
			&ast.DoLet{Name: "y", Value: &ast.Binary{Op: "+", L: local("x", types.Int), R: integer(2)}},
			&ast.DoExpr{X: call(ctor("Some"), local("y", types.Int))},
		},
		Result: call(ctor("Some"), local("y", types.Int)),
	}
	addFunc(p, "sequence", nil, nil, do)
	paramDict := types.DictRef{Kind: types.DictParam, Class: "Monad", Param: "M", ParamClass: "Monad"}
	polyDo := &ast.Do{ExprBase: annotated(&types.Ann{Type: types.Unit, Monad: &paramDict}), Stmts: do.Stmts, Result: do.Result}
	poly := addFunc(p, "genericSequence", nil, nil, polyDo)
	poly.Scheme.Constraints = []types.Constraint{{Class: "Monad", Arg: &types.TVar{Name: "M"}}}
	assertSource(t, p,
		"func genericSequence_(dict_M Monad) any",
		"(dict_M).Bind(&Option_Some{F0: int64(1)}, func(x_ any) any",
		"(Monad_Option{}).Bind(&Option_Some{F0: int64(1)}, func(x_ any) any",
		"var y_ any = rt.AddInt(x_, int64(2))",
		"(Monad_Option{}).Bind(&Option_Some{F0: y_}, func(_ any) any",
		"return &Option_Some{F0: y_}")
}

func TestNestedConstructorAndLiteralPatterns(t *testing.T) {
	p := fixture()
	option(p)
	match := &ast.Match{Scrut: local("x", types.Unit), Arms: []ast.Arm{
		{Pat: &ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PLit{X: integer(7)}}}}}, Body: integer(70)},
		{Pat: &ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PVar{Name: "n"}}}}}, Body: local("n", types.Int)},
		{Pat: &ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PCtor{Name: "None"}}}, Body: integer(1)},
		{Pat: &ast.PWild{}, Body: integer(0)},
	}}
	addFunc(p, "nested", []string{"x"}, []types.Type{types.Unit}, match)
	out := assertSource(t, p, "case *Option_Some:", "case *Option_None:", ".(int64) == int64(7)", "var n_ any =", "return n_", `panic("non-exhaustive match")`)
	if strings.Count(out, "case *Option_Some:") != 5 {
		t.Fatalf("nested/repeated outer constructor patterns lost their own continuation:\n%s", out)
	}
}

func TestExternWrappersAndImportDeduplication(t *testing.T) {
	p := fixture()
	extern(p, "foreign", []string{"input"}, []types.Type{types.String}, "example/foreign", "Echo")
	extern(p, "foreignAgain", []string{"value"}, []types.Type{types.Int}, "example/foreign", "Echo")
	extern(p, "unit", nil, nil, "gofx/rt", "UnitValue")
	extern(p, "show", []string{"number"}, []types.Type{types.Int}, "gofx/rt", "ShowInt")
	p.Main.Decl.Body.Result = call(function("unit", fnType()))
	out := assertSource(t, p,
		`ext_1 "example/foreign"`,
		`ext_2 "gofx/rt"`,
		"func foreign_(input_ any) any {\n\treturn ext_1.Echo(input_)",
		"return ext_2.UnitValue()",
		"return ext_2.ShowInt(number_)",
		"return unit_()")
	if strings.Count(out, `"example/foreign"`) != 1 {
		t.Fatalf("extern imports were not deduplicated:\n%s", out)
	}
}

func TestLocalsLambdasBlocksAndIdentifierMangling(t *testing.T) {
	p := fixture()
	lambdaType := fnType(types.Int)
	lambda := identity()
	applied := call(lambda, integer(6))
	applied.Fn.(*ast.Lambda).Ann = &types.Ann{Type: lambdaType}
	body := &ast.BlockExpr{Block: &ast.Block{Stmts: []ast.Stmt{
		&ast.LetStmt{Name: "type", Value: integer(1)},
		&ast.LetStmt{Name: "type", Value: local("type", types.Int)},
		&ast.LetStmt{Name: "dict_F", Value: local("type", types.Int)},
		&ast.LetStmt{Name: "ext_1", Value: integer(2)},
		&ast.ExprStmt{X: &ast.StringLit{Value: "discarded\n\"quoted\""}},
	}, Result: &ast.If{Cond: boolean(true), Then: local("dict_F", types.Int), Else: applied}}}
	addFunc(p, "switch", []string{"type"}, []types.Type{types.Int}, body)
	assertSource(t, p,
		"func switch_(type_ any) any",
		"var type_ any = type_",
		"var dict_F_ any = type_",
		"var ext_1_ any = int64(2)",
		`_ = "discarded\n\"quoted\""`,
		"if any(true).(bool)",
		"any(func(x_ any) any",
		").(func(any) any)(int64(6))")
}

func TestOperatorSelection(t *testing.T) {
	binary := []struct {
		op, name string
		value    ast.Expr
	}{
		{"+", "AddInt", integer(1)}, {"-", "SubInt", integer(1)}, {"*", "MulInt", integer(1)}, {"/", "DivInt", integer(1)},
		{"==", "EqInt", integer(1)}, {"!=", "NeInt", integer(1)}, {"<", "LtInt", integer(1)}, {"<=", "LeInt", integer(1)}, {">", "GtInt", integer(1)}, {">=", "GeInt", integer(1)},
		{"==", "EqString", text("a")}, {"!=", "NeString", text("a")}, {"<", "LtString", text("a")}, {"<=", "LeString", text("a")}, {">", "GtString", text("a")}, {">=", "GeString", text("a")},
		{"==", "EqBool", boolean(true)}, {"!=", "NeBool", boolean(true)}, {"&&", "And", boolean(true)}, {"||", "Or", boolean(true)},
	}
	for _, tt := range binary {
		t.Run(tt.name, func(t *testing.T) {
			p := fixture()
			p.Main.Decl.Body.Result = &ast.Binary{Op: tt.op, L: tt.value, R: tt.value}
			assertSource(t, p, "return rt."+tt.name+"(")
		})
	}
	for _, tt := range []struct {
		op, name string
		value    ast.Expr
	}{{"-", "NegInt", integer(1)}, {"!", "Not", boolean(false)}} {
		t.Run(tt.name, func(t *testing.T) {
			p := fixture()
			p.Main.Decl.Body.Result = &ast.Unary{Op: tt.op, X: tt.value}
			assertSource(t, p, "return rt."+tt.name+"(")
		})
	}
}

func TestGenerationErrors(t *testing.T) {
	p := fixture()
	p.Main.Decl.Body.Result = &ast.Ident{ExprBase: ast.ExprBase{Pos: ast.Pos{Line: 3, Col: 7}}, Name: "missing"}
	if _, err := Generate(p, "main"); err == nil || err.Error() != "3:7: expression has no annotation" {
		t.Fatalf("missing-annotation error = %v", err)
	}
	if _, err := Generate(nil, "main"); err == nil || err.Error() != "nil program" {
		t.Fatalf("nil-program error = %v", err)
	}
	if _, err := Generate(fixture(), "func"); err == nil || err.Error() != `invalid Go package name "func"` {
		t.Fatalf("package error = %v", err)
	}
	withoutMain := fixture()
	withoutMain.Main = nil
	if _, err := Generate(withoutMain, "main"); err == nil || err.Error() != "program has no main function" {
		t.Fatalf("missing-main error = %v", err)
	}
}

// Fixtures deliberately assemble semantic annotations without types.Check, so
// generator tests remain independent of the concurrently implemented checker.
func fixture() *types.Program {
	p := &types.Program{Classes: map[string]*types.Class{}, DataTypes: map[string]*types.DataType{}, Funcs: map[string]*types.FuncInfo{}}
	p.Main = addFunc(p, "main", nil, nil, integer(0))
	return p
}

func addFunc(p *types.Program, name string, names []string, params []types.Type, result ast.Expr) *types.FuncInfo {
	decl := &ast.FuncDecl{Name: name, Body: &ast.Block{Result: result}}
	for _, param := range names {
		decl.Params = append(decl.Params, ast.Param{Name: param})
	}
	f := &types.FuncInfo{Name: name, Decl: decl, Scheme: &types.Scheme{Type: &types.TFunc{Params: params, Ret: types.Unit}}}
	p.Funcs[name] = f
	return f
}

func extern(p *types.Program, name string, names []string, params []types.Type, path, symbol string) {
	f := addFunc(p, name, names, params, nil)
	f.Decl.Body = nil
	f.Decl.Extern = &ast.ExternRef{ImportPath: path, Name: symbol}
}

func option(p *types.Program) {
	d := &types.DataType{Name: "Option", TParams: []*types.TVar{{Name: "A"}}}
	d.Ctors = []*types.Ctor{{Name: "None", Data: d}, {Name: "Some", Data: d, Fields: []types.Type{types.Unit}, Index: 1}}
	p.DataTypes[d.Name] = d
}

func classFixture() (*types.Program, *types.Instance, *types.Instance) {
	p := fixture()
	option(p)
	functor := &types.Class{Name: "Functor", Param: &types.TVar{Name: "F"}}
	monad := &types.Class{Name: "Monad", Param: &types.TVar{Name: "M"}, Super: "Functor"}
	functor.Methods = []*types.Method{{Name: "fmap", Class: functor, Scheme: &types.Scheme{Type: fnType(types.Unit, fnType(types.Int))}}}
	monad.Methods = []*types.Method{
		{Name: "pure", Class: monad, Scheme: &types.Scheme{Type: fnType(types.Int)}},
		{Name: "bind", Class: monad, Scheme: &types.Scheme{Type: fnType(types.Unit, fnType(types.Int))}},
	}
	p.Classes[functor.Name], p.Classes[monad.Name] = functor, monad
	optionCon := &types.TCon{Name: "Option"}
	fi := &types.Instance{Class: functor, TypeCon: optionCon, Decl: &ast.InstanceDecl{Class: "Functor", TypeCon: "Option", Methods: []ast.InstMethod{{
		Name: "fmap", Params: []string{"fa", "f"}, Body: &ast.Block{Result: &ast.Match{Scrut: local("fa", types.Unit), Arms: []ast.Arm{
			{Pat: &ast.PCtor{Name: "None"}, Body: ctor("None")},
			{Pat: &ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PVar{Name: "a"}}}, Body: call(ctor("Some"), call(local("f", fnType(types.Int)), local("a", types.Int)))},
		}}},
	}}}}
	mi := &types.Instance{Class: monad, TypeCon: optionCon, Decl: &ast.InstanceDecl{Class: "Monad", TypeCon: "Option", Methods: []ast.InstMethod{
		{Name: "pure", Params: []string{"a"}, Body: &ast.Block{Result: call(ctor("Some"), local("a", types.Int))}},
		{Name: "bind", Params: []string{"ma", "f"}, Body: &ast.Block{Result: &ast.Match{Scrut: local("ma", types.Unit), Arms: []ast.Arm{
			{Pat: &ast.PCtor{Name: "None"}, Body: ctor("None")},
			{Pat: &ast.PCtor{Name: "Some", Args: []ast.Pattern{&ast.PVar{Name: "a"}}}, Body: call(local("f", fnType(types.Int)), local("a", types.Int))},
		}}}},
	}}}
	p.Instances = []*types.Instance{fi, mi}
	return p, fi, mi
}

func annotated(ann *types.Ann) ast.ExprBase { return ast.ExprBase{Ann: ann} }

func fnType(params ...types.Type) *types.TFunc { return &types.TFunc{Params: params, Ret: types.Unit} }

func integer(value int64) *ast.IntLit {
	return &ast.IntLit{ExprBase: annotated(&types.Ann{Type: types.Int}), Value: value}
}

func text(value string) *ast.StringLit {
	return &ast.StringLit{ExprBase: annotated(&types.Ann{Type: types.String}), Value: value}
}

func boolean(value bool) *ast.BoolLit {
	return &ast.BoolLit{ExprBase: annotated(&types.Ann{Type: types.Bool}), Value: value}
}

func local(name string, typ types.Type) *ast.Ident {
	return &ast.Ident{Name: name, ExprBase: annotated(&types.Ann{Type: typ, Ref: types.RefLocal})}
}

func function(name string, typ *types.TFunc, dicts ...types.DictRef) *ast.Ident {
	return &ast.Ident{Name: name, ExprBase: annotated(&types.Ann{Type: typ, Ref: types.RefFunc, Dicts: dicts})}
}

func method(name string, typ *types.TFunc, dict types.DictRef) *ast.Ident {
	return &ast.Ident{Name: name, ExprBase: annotated(&types.Ann{Type: typ, Ref: types.RefMethod, Dicts: []types.DictRef{dict}})}
}

func ctor(name string) *ast.Ident {
	return &ast.Ident{Name: name, ExprBase: annotated(&types.Ann{Type: types.Unit, Ref: types.RefCtor})}
}

func call(fn ast.Expr, args ...ast.Expr) *ast.Call {
	return &ast.Call{Fn: fn, Args: args, ExprBase: annotated(&types.Ann{Type: types.Unit})}
}

func identity() *ast.Lambda {
	return &ast.Lambda{ExprBase: annotated(&types.Ann{Type: fnType(types.Int)}), Params: []ast.Param{{Name: "x"}}, Body: local("x", types.Int)}
}

func instanceDict(instance *types.Instance) types.DictRef {
	return types.DictRef{Kind: types.DictInstance, Class: instance.Class.Name, Instance: instance}
}

func assertSource(t *testing.T, p *types.Program, fragments ...string) string {
	t.Helper()
	source, err := Generate(p, "main")
	if err != nil {
		t.Fatal(err)
	}
	formatted, err := format.Source(source)
	if err != nil || !bytes.Equal(source, formatted) {
		t.Fatalf("output is not gofmt-formatted: %v\n%s", err, source)
	}
	fset := token.NewFileSet()
	file, err := goparser.ParseFile(fset, "generated.go", source, goparser.AllErrors)
	if err != nil {
		t.Fatalf("output does not parse: %v\n%s", err, source)
	}
	config := gotypes.Config{Importer: fakeImporter{}}
	if _, err := config.Check("generated", fset, []*goast.File{file}, nil); err != nil {
		t.Fatalf("output does not type-check: %v\n%s", err, source)
	}
	for _, fragment := range fragments {
		if !strings.Contains(string(source), fragment) {
			t.Errorf("missing fragment %q:\n%s", fragment, source)
		}
	}
	return string(source)
}

// The fake importer checks the erased external ABI without importing rt or
// compiling the runtime worker's source. It does not replace any gofx lowering.
type fakeImporter struct{}

func (fakeImporter) Import(path string) (*gotypes.Package, error) {
	pkg := gotypes.NewPackage(path, path[strings.LastIndex(path, "/")+1:])
	var funcs map[string]int
	switch path {
	case "gofx/rt":
		funcs = map[string]int{"RunMain": 1, "UnitValue": 0, "ShowInt": 1}
		for _, name := range strings.Fields("AddInt SubInt MulInt DivInt EqInt NeInt LtInt LeInt GtInt GeInt EqString NeString LtString LeString GtString GeString EqBool NeBool And Or") {
			funcs[name] = 2
		}
		funcs["NegInt"], funcs["Not"] = 1, 1
	case "example/foreign":
		funcs = map[string]int{"Echo": 1}
	default:
		return nil, fmt.Errorf("unexpected import %q", path)
	}
	anyType := gotypes.Universe.Lookup("any").Type()
	for name, arity := range funcs {
		params := make([]*gotypes.Var, arity)
		for i := range params {
			params[i] = gotypes.NewVar(token.NoPos, pkg, fmt.Sprintf("a%d", i), anyType)
		}
		var results *gotypes.Tuple
		if name != "RunMain" {
			results = gotypes.NewTuple(gotypes.NewVar(token.NoPos, pkg, "", anyType))
		}
		sig := gotypes.NewSignatureType(nil, nil, nil, gotypes.NewTuple(params...), results, false)
		pkg.Scope().Insert(gotypes.NewFunc(token.NoPos, pkg, name, sig))
	}
	pkg.MarkComplete()
	return pkg, nil
}
